        k,h,w=m[1],int(m[2]),int(m[3])
        seg=t[m.end():].split('\n')[:h]
        g=[[int(x) for x in r.split()] for r in seg] if all(len(r.split())==w and all(x.isdigit() for x in r.split()) for r in seg) else None
