def comps(mask, diag=False):
    h=len(mask); w=len(mask[0]); seen=set(); out=[[0]*w for _ in range(h)]
    import collections
    st=[]
    for i in range(h):
        for j in range(w):
            if mask[i][j] and (i,j) not in seen:
                n=1; st.append((i,j)); seen.add((i,j)); comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and mask[x][y] and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                for a,b in comp: out[a][b]=1
    return out
